import { DOCUMENT, Injectable, InjectionToken, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { NEVER, Observable, of, shareReplay, catchError, map, switchMap } from 'rxjs';
import { ContentIndex, DocPage, SearchDoc, SectionIndex } from './content.models';
import { CONTENT_BUILD_ID } from './content-build';

/** The payload build this app was compiled with (generated by build-content.mjs). */
export const CONTENT_BUILD = new InjectionToken<string>('CONTENT_BUILD', {
  providedIn: 'root',
  factory: () => CONTENT_BUILD_ID,
});

/** Reloads the page. A token so a spec can count the call instead of losing Karma. */
export const RELOAD_PAGE = new InjectionToken<() => void>('RELOAD_PAGE', {
  providedIn: 'root',
  factory: () => {
    const win = inject(DOCUMENT).defaultView;
    return () => win?.location.reload();
  },
});

/** The sessionStorage key that stops a reload loop: one reload per app/payload pair. */
export const RELOAD_GUARD_KEY = 'hug-content-reload';

/**
 * Where the index stands relative to this app's build.
 *   loading      the index has not settled yet
 *   current      index.json carries this app's build id: trust it, empty means empty
 *   reloading    the server's payload is from another build: the page is reloading
 *   other-build  still another build after one reload (or no way to guard one):
 *                render what it has, but never claim a tab is empty
 *   failed       index.json could not be read at all (see indexFailed)
 */
export type PayloadState = 'loading' | 'current' | 'reloading' | 'other-build' | 'failed';

/**
 * Reads the static content payload generated by scripts/build-content.mjs.
 *
 * Three fetches exist, with deliberately different caching:
 *   index.json   — tiny, needed by the nav on every route: fetched once, replayed.
 *   <doc>.json   — one per page: fetched on navigation, memoised per route so
 *                  going back to a page you have read is instant.
 *   search.json  — the largest payload: NOT fetched until the reader actually
 *                  searches, so the common case never pays for it.
 *
 * Every one is requested as `<file>?v=<build id>`. The files keep their paths (an
 * old cached shell still finds them), but a browser that cached another build's
 * index.json under the bare URL no longer hands it to this app (hugmesh.github.io#42).
 * The query alone is not trusted: an edge can ignore it, so the index's own
 * `buildId` is compared with this app's, and a mismatch is re-read past every cache.
 */
@Injectable({ providedIn: 'root' })
export class ContentService {
  private readonly http = inject(HttpClient);
  private readonly build = inject(CONTENT_BUILD);
  private readonly reloadPage = inject(RELOAD_PAGE);
  private readonly storage = inject(DOCUMENT).defaultView;
  private readonly base = 'assets/content';

  /** Set when index.json cannot be read at all. The layout shows an honest
   *  message instead of an empty nav that looks like "there are no docs". */
  readonly indexFailed = signal(false);

  /** Whether the index that settled is this app's build. Read by the section page,
   *  which may only say "nothing is published" about a current index. */
  readonly payload = signal<PayloadState>('loading');

  private index$?: Observable<ContentIndex>;
  private search$?: Observable<readonly SearchDoc[]>;
  private readonly pages = new Map<string, Observable<DocPage | null>>();

  /** The build-stamped address of one payload file. */
  private url(file: string): string {
    return `${this.base}/${file}?v=${encodeURIComponent(this.build)}`;
  }

  index(): Observable<ContentIndex> {
    this.index$ ??= this.readIndex(false).pipe(
      // Another build's index, or one without the shape this app reads: read it
      // ONCE more past the browser cache (cache: 'reload') and the edge (a fresh
      // query value, since a bypassed browser cache still meets a cached edge).
      // `confirmed`: the index in hand came from a read past the caches. A re-read
      // that failed confirms nothing, so it never leads to a reload.
      switchMap((idx) =>
        idx && !this.isCurrent(idx)
          ? this.readIndex(true).pipe(map((fresh) => ({ idx: fresh ?? idx, confirmed: fresh !== null })))
          : of({ idx, confirmed: true }),
      ),
      switchMap(({ idx, confirmed }) => {
        if (!idx) {
          this.indexFailed.set(true);
          this.payload.set('failed');
          return of(EMPTY_INDEX);
        }
        if (this.isCurrent(idx)) {
          this.payload.set('current');
          return of(idx);
        }
        // Past every cache and still another build: the server has moved on and this
        // app is the stale side. A hash cannot say which is newer, but a fresh read is
        // the server's present, so reload once to pick up the shell that matches it.
        if (confirmed && this.reloadOnce(idx.buildId)) {
          this.payload.set('reloading');
          return NEVER;
        }
        this.payload.set('other-build');
        return of(idx);
      }),
      shareReplay({ bufferSize: 1, refCount: false }),
    );
    return this.index$;
  }

  section(id: string): Observable<SectionIndex | undefined> {
    return this.index().pipe(map((idx) => idx.sections.find((s) => s.id === id)));
  }

  /** Resolve one page. A missing file yields `null` rather than an error: a stale
   *  bookmark to a retired doc is an expected condition, and the page component
   *  renders a "moved or removed" state for it. */
  page(section: string, slug: string): Observable<DocPage | null> {
    const key = `${section}/${slug}`;
    let cached = this.pages.get(key);
    if (!cached) {
      cached = this.http.get<DocPage>(this.url(`${key}.json`)).pipe(
        catchError(() => of(null)),
        shareReplay({ bufferSize: 1, refCount: false }),
      );
      this.pages.set(key, cached);
    }
    return cached;
  }

  searchIndex(): Observable<readonly SearchDoc[]> {
    this.search$ ??= this.http.get<SearchDoc[]>(this.url('search.json')).pipe(
      catchError(() => of([])),
      shareReplay({ bufferSize: 1, refCount: false }),
    );
    return this.search$;
  }

  private readIndex(fresh: boolean): Observable<ContentIndex | null> {
    const url = fresh ? `${this.url('index.json')}&fresh=${Date.now()}` : this.url('index.json');
    return this.http
      .get<ContentIndex>(url, fresh ? { cache: 'reload' } : {})
      .pipe(catchError(() => of(null)));
  }

  /** This app's build, and the shape the tab pages read. Never judged by shape
   *  alone: an index can have every field and still be another build's. */
  private isCurrent(idx: ContentIndex): boolean {
    return (
      idx.buildId === this.build &&
      Array.isArray(idx.sections) &&
      idx.sections.every((s) => Array.isArray(s.groups) && Array.isArray(s.docs))
    );
  }

  /** Reload, unless this app already reloaded for this payload in this tab. With no
   *  usable sessionStorage there is no loop guard, so no reload either. */
  private reloadOnce(payloadBuild: string | undefined): boolean {
    const mark = `${this.build}>${payloadBuild ?? 'none'}`;
    try {
      const store = this.storage?.sessionStorage;
      if (!store || store.getItem(RELOAD_GUARD_KEY) === mark) return false;
      store.setItem(RELOAD_GUARD_KEY, mark);
    } catch {
      return false;
    }
    this.reloadPage();
    return true;
  }
}

const EMPTY_INDEX: ContentIndex = {
  generatedFrom: '',
  sectionOrder: [],
  sections: [],
  totals: { sections: 0, pages: 0, diagrams: 0 },
};
